      const Stmt *const *LastPtr = State->get<CompLastUseStmt>(B);
      const Stmt *Last = LastPtr ? *LastPtr : nullptr;
      reportMissingGuard(B, Last, C);
      Reported = true;
    }
  }

  // If we reported, we are done. No need to mutate state here for now.
  (void)Reported;
}

